using Godot;
using System;
using System.Collections.Generic;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsInspectorOperations
{
    public void bones(RefCounted owner)
    {
        var actor=Actor(owner);var model=Model(owner);var panel=Panel(owner);var host=Host(owner);var settings=Initial(owner);var bones=Get(actor.Get("values").AsGodotDictionary(),"rig_bones",new GArray()).AsGodotArray();if(bones.Count==0){heading(owner,"Select the model's Skeleton Rig actor to choose bones. Import or rig a model first.");foreach(var value in model.Get("actors").AsGodotArray()){var candidate=value.As<Resource>();if(Get(candidate.Get("values").AsGodotDictionary(),"rig_bones",new GArray()).AsGodotArray().Count==0)continue;var select=new Button{Text="Select "+candidate.Get("display_name").AsString()};panel.AddChild(select);select.Pressed+=()=>{var clip=model.Call("clip_for_actor_id",candidate.Get("id")).As<Resource>();if(clip!=null){model.Call("select",clip.Get("id"));host.CallDeferred("select_main_tab","Actor");host.CallDeferred("select_section","Physics");}};}return;}var search=new LineEdit{PlaceholderText="Search bones…",Text=actor.GetMeta("physics_bone_search","").AsString()};panel.AddChild(search);var tree=new Tree{Name="PhysicsBones",HideRoot=true,SelectMode=Tree.SelectModeEnum.Multi,CustomMinimumSize=new Vector2(0,150)};panel.AddChild(tree);var root=tree.CreateItem();var items=new List<TreeItem>();for(int i=0;i<bones.Count;i++){var bone=bones[i].AsGodotDictionary();int parent=bone["parent"].AsInt32();var item=tree.CreateItem(parent>=0&&parent<items.Count?items[parent]:root);item.SetCellMode(0,TreeItem.TreeCellMode.Check);item.SetText(0,bone["name"].AsString());item.SetMetadata(0,i);item.SetEditable(0,true);item.SetChecked(0,settings["bones"].AsGodotArray().Contains(bone["name"].AsString()));items.Add(item);}void Filter(string text){actor.SetMeta("physics_bone_search",text);foreach(var item in items)item.Visible=text.Length==0||item.GetText(0).ToLowerInvariant().Contains(text.ToLowerInvariant(),StringComparison.Ordinal);foreach(var item in items)if(item.Visible){var parent=item.GetParent();while(parent!=null){parent.Visible=true;parent=parent.GetParent();}}}search.TextChanged+=Filter;Filter(search.Text);tree.ItemEdited+=()=>{var selected=_settings.authored(actor)["bones"].AsGodotArray().Duplicate();var edited=tree.GetEdited();string name=edited.GetText(0);if(edited.IsChecked(0)&&!selected.Contains(name))selected.Add(name);else if(!edited.IsChecked(0))selected.Remove(name);change(owner,"bones",selected,true);};GArray SelectedNames(){var names=new GArray();var item=tree.GetNextSelected(null);while(item!=null){names.Add(item.GetText(0));item=tree.GetNextSelected(item);}return names;}string Name(int i)=>bones[i].AsGodotDictionary()["name"].AsString();int Parent(int i)=>bones[i].AsGodotDictionary()["parent"].AsInt32();var controls=new HFlowContainer();panel.AddChild(controls);foreach(string name in new[]{"All","None","Selected","Children","Chain","Mirror"}){string action=name;var button=new Button{Text=action};controls.AddChild(button);button.Pressed+=()=>{var chosen=SelectedNames();var affected=_settings.authored(actor)["bones"].AsGodotArray().Duplicate();if(chosen.Count==0&&action is not ("All" or "None"))chosen=affected.Duplicate();if(action=="All"){affected.Clear();chosen.Clear();for(int i=0;i<bones.Count;i++)chosen.Add(Name(i));}if(action=="None"){affected.Clear();chosen.Clear();}if(action=="Children")for(int i=0;i<bones.Count;i++){int parent=Parent(i);bool include=false;var visited=new HashSet<int>();while(parent>=0&&parent<bones.Count&&visited.Add(parent)){if(chosen.Contains(Name(parent))){include=true;break;}parent=Parent(parent);}if(include)chosen.Add(Name(i));}if(action=="Chain")foreach(var value in chosen.Duplicate()){string name=value.AsString();int index=-1;for(int i=0;i<bones.Count;i++)if(Name(i)==name){index=i;break;}if(index<0)continue;int parent=Parent(index);var path=new List<string>();var visited=new HashSet<int>();while(parent>=0&&parent<bones.Count&&visited.Add(parent)){path.Add(Name(parent));if(chosen.Contains(Name(parent))){foreach(string link in path)if(!chosen.Contains(link))chosen.Add(link);break;}parent=Parent(parent);}visited.Clear();while(index>=0&&visited.Add(index)){var children=new List<int>();for(int i=0;i<bones.Count;i++)if(Parent(i)==index)children.Add(i);if(children.Count!=1)break;index=children[0];if(!chosen.Contains(Name(index)))chosen.Add(Name(index));}}if(action=="Mirror")foreach(var value in chosen.Duplicate())foreach(var pair in new[]{new[]{".L",".R"},new[]{"_L","_R"},new[]{"Left","Right"},new[]{"left","right"}}){string name=value.AsString();string mirror=name.Contains(pair[0],StringComparison.Ordinal)?name.Replace(pair[0],pair[1],StringComparison.Ordinal):name.Replace(pair[1],pair[0],StringComparison.Ordinal);for(int i=0;i<bones.Count;i++)if(Name(i)==mirror&&!chosen.Contains(mirror))chosen.Add(mirror);}foreach(var value in chosen)if(!affected.Contains(value))affected.Add(value);change(owner,"bones",affected,true);};}
        var overrides=fold(owner,"Selected bone settings");host.Call("_add_label",overrides,"Applies to highlighted bones, or all checked bones.");var enabled=new CheckButton{Text="Bone physics enabled",ButtonPressed=true};overrides.AddChild(enabled);Settings Amend(string key,Variant value){var names=SelectedNames();if(names.Count==0)names=_settings.authored(actor)["bones"].AsGodotArray();var data=_settings.authored(actor)["bone_settings"].AsGodotDictionary().Duplicate(true);foreach(var name in names){if(!data.ContainsKey(name))data[name]=new Settings();data[name].AsGodotDictionary()[key]=value;}return data;}enabled.Toggled+=value=>change(owner,"bone_settings",Amend("enabled",value),false);foreach(string field in new[]{"influence","stiffness","damping","gravity","mass","limit","radius"}){string key=field;host.Call("_add_label",overrides,key.Capitalize());var number=Number();number.Step=.01;number.MinValue=0;number.MaxValue=key=="influence"?1:1000;number.SetValueNoSignal(settings[key].AsDouble());overrides.AddChild(number);StructuredNumber(owner,number,"bone_settings",value=>Amend(key,value));void Refresh(){var names=SelectedNames();if(names.Count==0)names=_settings.authored(actor)["bones"].AsGodotArray();if(names.Count==0||number.Get("dragging").AsBool())return;var config=Sample(owner);var individual=Get(config["bone_settings"].AsGodotDictionary(),names[0].AsString(),new Settings()).AsGodotDictionary();number.SetValueNoSignal(Get(individual,key,config[key]).AsDouble());}tree.MultiSelected+=(_,_,_)=>Refresh();Update(owner,Callable.From(Refresh));}
    }
}
